namespace Vialiq.Core.Models;

using System.Collections.Generic;

/// <summary>
/// Change manifest generated by the Migration Diff Engine during protocol upversioning.
/// Pinpoints the exact modified forms, visits, and codelists requiring cache rebuild.
/// </summary>
/// <param name="AmendmentId">The unique identifier of the protocol amendment.</param>
/// <param name="TenantId">The sponsor tenant identifier.</param>
/// <param name="StudyId">The clinical study identifier.</param>
/// <param name="TargetVersion">The new approved protocol version string.</param>
/// <param name="ModifiedFormIds">List of CRF form identifiers modified or added in this amendment.</param>
/// <param name="ModifiedVisitIds">List of visit schedule identifiers affected by this amendment.</param>
/// <param name="ModifiedCodelistIds">List of codelist identifiers modified by this amendment.</param>
/// <param name="RequiresRetrospectiveRecalculation">Indicates whether existing data points require retrospective rule re-evaluation.</param>
public sealed record ProtocolAmendmentManifest(
    string AmendmentId,
    string TenantId,
    string StudyId,
    string TargetVersion,
    IReadOnlyList<string> ModifiedFormIds,
    IReadOnlyList<string> ModifiedVisitIds,
    IReadOnlyList<string> ModifiedCodelistIds,
    bool RequiresRetrospectiveRecalculation = false);
